-- Karazhan: Chess Event.
-- The 32 pieces are spawned on the squares of the board, the pieces and Echo of Medivh get their scripts, the pet bar
-- spells of the pieces and the gossip that starts the game. The chess spells pick their targets (squares, pieces,
-- stalkers) through implicit target conditions. Spell 39394 is not in the client data, so it is defined here as a
-- server-side spell; it fires the victory visual 39395 five times per second after the win. Spell effect id 303400 is
-- provisional.

DELETE FROM `creature` WHERE `guid` BETWEEN 8319900 AND 8319931;

-- Move, facing and two actions on the pet bar of a controlled piece
UPDATE `creature_template` SET `spell1` = 37146, `spell2` = 30284, `spell3` = 37406, `spell4` = 37414, `ScriptName` = 'npc_chess_piece' WHERE `entry` = 17211;
UPDATE `creature_template` SET `spell1` = 37146, `spell2` = 30284, `spell3` = 37413, `spell4` = 37416, `ScriptName` = 'npc_chess_piece' WHERE `entry` = 17469;
UPDATE `creature_template` SET `spell1` = 37151, `spell2` = 30284, `spell3` = 37427, `spell4` = 37432, `ScriptName` = 'npc_chess_piece' WHERE `entry` = 21160;
UPDATE `creature_template` SET `spell1` = 37144, `spell2` = 30284, `spell3` = 37453, `spell4` = 37498, `gossip_menu_id` = 8346, `npcflag` = 1, `ScriptName` = 'npc_chess_piece' WHERE `entry` = 21664;
UPDATE `creature_template` SET `spell1` = 37152, `spell2` = 30284, `spell3` = 37455, `spell4` = 37459, `ScriptName` = 'npc_chess_piece' WHERE `entry` = 21682;
UPDATE `creature_template` SET `spell1` = 37148, `spell2` = 30284, `spell3` = 37462, `spell4` = 37465, `ScriptName` = 'npc_chess_piece' WHERE `entry` = 21683;
