UPDATE `creature_template` SET `spell1` = 37151, `spell2` = 30284, `spell3` = 37428, `spell4` = 37434, `gossip_menu_id` = 8355, `npcflag` = 1, `ScriptName` = 'npc_chess_piece' WHERE `entry` = 21726;
UPDATE `creature_template` SET `spell1` = 37152, `spell2` = 30284, `spell3` = 37456, `spell4` = 37461, `gossip_menu_id` = 8362, `npcflag` = 1, `ScriptName` = 'npc_chess_piece' WHERE `entry` = 21747;
UPDATE `creature_template` SET `spell1` = 37144, `spell2` = 30284, `spell3` = 37454, `spell4` = 37502, `ScriptName` = 'npc_chess_piece' WHERE `entry` = 21748;
UPDATE `creature_template` SET `spell1` = 37148, `spell2` = 30284, `spell3` = 37463, `spell4` = 37469, `ScriptName` = 'npc_chess_piece' WHERE `entry` = 21750;
UPDATE `creature_template` SET `spell1` = 37153, `spell2` = 30284, `spell3` = 37476, `spell4` = 37472, `gossip_menu_id` = 8368, `npcflag` = 1, `ScriptName` = 'npc_chess_piece' WHERE `entry` = 21752;
UPDATE `creature_template` SET `ScriptName` = 'npc_echo_of_medivh' WHERE `entry` = 16816;

-- The pieces fight with the melee timer; the charger and the cleric also carry Invisibility and Stealth Detection
DELETE FROM `creature_template_addon` WHERE `entry` IN (17211, 17469, 21160, 21664, 21682, 21683, 21684, 21726, 21747, 21748, 21750, 21752);

-- Echo of Medivh offers the friendly game after the win
DELETE FROM `gossip_menu_option` WHERE `MenuID` = 8404;

DELETE FROM `creature_text` WHERE `entry` = 16816;

-- Victory Visual (Chess)
DELETE FROM `spell_dbc` WHERE `Id` = 39394;
DELETE FROM `spellmisc_dbc` WHERE `Id` = 239394;
DELETE FROM `spelleffect_dbc` WHERE `EffectSpellId` = 39394;

DELETE FROM `spell_script_names` WHERE `spell_id` IN (30012, 30284, 32227, 32228, 37142, 37143, 37144, 37146, 37147, 37148, 37149, 37150, 37151, 37152, 37153, 37220, 37337, 37339, 37345, 37348, 37366, 37775, 37824, 39331, 39338, 39341, 39342, 39344, 39395, 39398, 45260);

-- Targets of the chess spells: squares for the moves, the pieces of one side for the melee actions and the cheats, the
-- stalker next to the board for the transforms. A transform may only take a stalker that is not yet transformed.
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 13 AND `SourceEntry` IN (30012, 30284, 30532, 32227, 32228, 37142, 37143, 37144, 37146, 37147, 37148, 37149, 37150, 37151, 37152, 37153, 37220, 37337, 37339, 37345, 37348, 37366, 37775, 39338, 39341, 39342, 39344, 39350, 39352, 39353, 39354, 39355, 39356, 39357, 39358, 39359, 39360, 39361, 39362, 39395, 39398, 39399, 39401);
